def report(o):
 base=o
 if (o/'analysis_pointer.json').exists():o=Path(read(o/'analysis_pointer.json')['analysis'])
 s=read(o/'summary.json');cov=read(o/'coverage.json');rv=read(o/'adversarial_review.json');findings=read(o/'findings.json');quests=read(o/'quest_results.json');pairs=read(o/'resource_parity.json');protection=read(base/'protection_after.json');cat=read(o/'catalogues.json');src=read(base/'source_identity_inventory.json');tests=read(base/'corpus_mutation_tests.json');handlers=read(o/'handler_coverage.json') if (o/'handler_coverage.json').exists() else {};kinds=collections.Counter(f['kind'] for f in findings);fail=[f for f in findings if f['status']=='FAIL'];selected=[r for r in quests if r['selection']=='INCLUDE'];unmapped=[r['id'] for r in selected if not r['private_root_candidates'] or not r['native_root_candidates']];donors=read(o/'corrected_donor_checks.json');no_model=sum(r['status']=='OPAQUE' for r in pairs);root=Path(read(o/'prepared.json')['candidate'])
 suite=read(base/'mutation_suite.json');recon=read(o/'catalogue_reconciliation.json');triage=read(o/'dependency_triage_summary.json');capture=read(o/read(o/'capture_pointer.json')['capture']);managed=len(read(read(o/'prepared.json')['manifest'])['package_files']);alias_gaps=recon['registry_ids_missing_declaration_and_entry'];priorities=[]
 for f in findings:
  if f['status']=='FAIL':priorities.append({'priority':'P1','classification':'FAIL','finding':f['id'],'kind':f['kind'],'resource':f.get('resource'),'evidence':f,'interpretation':'Static model violation; inspect route feasibility before declaring a gameplay defect'})
 for priority,kind,detail in [('P1','UNRESOLVED_SEMANTIC_DIFFERENCES',{'resources':sum(r['status']=='UNKNOWN' for r in pairs),'registry':'intentional_differences.json'}),('P1','ROOT_ASSOCIATION_UNPROVED',{'selected_quests':unmapped}),('P2','OPAQUE_ASSET_CONTENT',{'resources':no_model,'decode_errors':cov['decode_error_count']}),('P2','PROVIDER_PRECEDENCE',{'ambiguous_depots':s['provider_ambiguities']}),('P2','DEPENDENCY_EVIDENCE_GAPS',{'queried_missing':len(cov['capture_missing']),'unqueried':len(cov['not_in_capture'])}),('P2','INDEPENDENT_TRAVERSAL_GAPS',{'raw_model_node_mismatches':len(rv['raw_node_mismatches']),'unqueried_references':len(rv['references_unqueried'])}),('P2','SAVED_IDENTITIES',src['persistence_baseline']['resource_changes_requiring_identity_review'])]:priorities.append({'priority':priority,'classification':'UNKNOWN','kind':kind,'detail':detail})
 write(o/'prioritized_discrepancies.json',priorities);csvwrite(o/'prioritized_discrepancies.csv',[{'priority':r['priority'],'classification':r['classification'],'kind':r['kind'],'evidence':r} for r in priorities])
 priorities.append({'priority':'P1','classification':'UNKNOWN','kind':'ADAPTER_ALIAS_MAPPING_UNRESOLVED','detail':{'selected_ids':alias_gaps,'unmapped_entry_like_bindings':recon['entry_like_bindings_not_mapped'],'limit':'Many have shortened/generic root candidates; this is not proof of missing restoration'}})
 write(o/'prioritized_discrepancies.json',priorities);csvwrite(o/'prioritized_discrepancies.csv',[{'priority':r['priority'],'classification':r['classification'],'kind':r['kind'],'evidence':r} for r in priorities])
 def link(name):return f'[{name}]({name})'
 def table(d):return '\n'.join(f'| {k} | {v} |' for k,v in sorted(d.items()))
 lines=['# PH3 static vanilla-parity audit','', '**Result: executed with unresolved coverage; no blanket parity PASS.** Static findings do not certify gameplay. No restoration fixes were implemented.','',f"Baseline: `{root}`. The installed/package/source readbacks cover {s['resources_discovered']} discovered depots, {cov['private_resource_readbacks']} of {cov['total_private']} PTFR payloads, and all 51 managed paths. The candidate manifest and ZIP hashes are in prepared.json; capture records all 134 archive providers without silently ranking differing providers.",'', '## Catalogue and measured coverage','', '| Category | Count |','| --- | ---: |',table(cat['derived_counts']),'',f"Held IDs: {', '.join(cat['held_ids'])}. Selection is derived from the actual current pointer, not historical counts. The current pointer has later v6.2/history overrides; older KB R6.1/pre-Tower-only wording is not the effective catalogue.",'','| Selected-quest result | Count |','| --- | ---: |',table(s['selected_quest_results']),'', '| Resource-comparison result | Count |','| --- | ---: |',table(s['resource_comparisons']),'',f"Normalized graph resources: {s['decoded_graph_resources']}; graph nodes: {s['graph_nodes']}; MAY-execution resources: {s['execution_context_resources']}; phone request contracts: {s['phone_contracts']}. Original/private handler inventory: {handlers.get('handlers','not generated')} tagged handlers across {handlers.get('decoded_nodes_examined','unknown')} normalized nodes. These are evidence-volume counts, not parity percentages.",'',f"Every {len(quests)} catalogue row has eight stage records. {len(unmapped)} selected quests lack a confident restored/vanilla root association. The full list is in prioritized_discrepancies.json. Shared roots, conditions and ownership remain bounded; catalogue coverage does not imply handler correctness.",'','## Verified static evidence','',f"- PH3 private payload readback: {cov['private_resource_readbacks']}/{cov['total_private']}; packaged ZIP CRC/hash checks and installed hashes are in prepared.json.",f"- CR1 exact-donor checks: {dict(collections.Counter(r['status'] for r in donors))}. A changed donor can be a documented successor; it remains unresolved until that exact successor is checked.",f"- All {len(src['files'])} packaged REDscript sources match the older persistence baseline. {len(src['persistent_fields'])} persistent declarations were inventoried lexically; {len(src['persistence_baseline']['resource_changes_requiring_identity_review'])} old resource payloads changed and require identity/lifecycle review.",f"- Literal mutation suite: 13 tests. Real-input corpus suite: {tests['run']} tests, success={tests['success']}. Historical CR1 donor regression, PH1 listener/cleanup omission, PH2 generated-ID collision and PH3 root-studio omission are represented. Tests mutate memory only.",'','## Prioritized discrepancies and blockers','',f"Static FAIL findings: **{len(fail)}**. Exact graph/node/fact/socket evidence is in findings.json and prioritized_discrepancies.json. FAIL under MAY-reachability is not a measured live route or a confirmed user-facing symptom.",'','| Finding kind | Count |','| --- | ---: |',table(kinds),'',f"Queried missing references: {len(cov['capture_missing'])}; decode errors: {cov['decode_error_count']}; ambiguous provider depots: {s['provider_ambiguities']}. Missing native lip-sync/cut references must be distinguished from mod-introduced omissions. Presence-only actors, prefabs, workspots, cameras and variants do not establish their semantic bindings.",'',f"Adversarial review: **{rv['status']}**; raw/model node-count mismatches: {len(rv['raw_node_mismatches'])}; stage-record errors: {len(rv['stage_errors'])}; unqueried references: {len(rv['references_unqueried'])}. The review uses a separately implemented raw traversal and independent catalogue reload. It is not an independent human/agent review.",'','## Limits and live-only behavior','', 'The engine inventories conditions, journals, facts, messages, rewards and cleanup edges and compares normalized resources. It does not formally solve branch satisfiability, every native-vs-private lifecycle contract, interrupt ordering, shared leases, duplicate reward paths, dynamic REDscript references or saved-owner migration. Unreviewed legitimate Tower/R4/history adaptations stay UNKNOWN, not errors; only evidence-pinned exceptions are approved. Asset internals and placements remain OPAQUE where not decoded. Actual calls, SMS UI, actors, doors, streaming, timing, rewards, interruptions and save/reload behavior require external runtime evidence. No game test is requested by this report.','', '## Preservation and reproducibility','',f"Protection: **{protection['status']}**, {protection['hashes_verified']} protected file hashes verified; {len(protection['hash_discrepancies'])} hash discrepancies; {len(protection['game_metadata_changes'])} game-tree metadata changes; {len(protection['save_metadata_changes'])} save-tree metadata changes. This verifies the stated hash/metadata scope, not an attribution of changes made by another process.",'', 'The original failed extractor and interrupted pre-certification normalization trial are retained as non-final evidence. Independent JSON closure exposed omitted references, DLC prefixes and sentinel handling; the final accepted capture is named in capture_pointer.json. The final analysis pointer identifies any corrected successor. The tool README provides the fresh-output reproduction commands. No historical builder, deployment script, game launch, runtime resource edit, save/fact write or release change was performed.','', '## Evidence files','']
 lines=[line.replace('all 51 managed paths',f'all {managed} managed paths').replace('all 134 archive providers',f'all {len(capture["archives"])} archive providers').replace('Literal mutation suite: 13 tests. Real-input corpus suite: '+str(tests['run'])+' tests, success='+str(tests['success']),f'Mutation suites: {suite["groups"]["literal"]} literal and {suite["groups"]["corpus"]} real-input tests; {suite["tests_run"]} total, success={suite["success"]}') for line in lines]
 lines=[f"All {len(quests)} catalogue rows have eight stage records. Basic ID/path/journal root candidates exist for every selected quest; this does not prove exact adapter identity or ownership. The independent reconciliation still has {len(alias_gaps)} selected IDs and {len(recon['entry_like_bindings_not_mapped'])} generic bindings requiring explicit alias mapping. Catalogue coverage does not imply handler correctness." if line.startswith('Every ') else line for line in lines]
 lines.extend(['','## Additional investigated coverage gaps','',f"Independent manifest/registration reconciliation leaves **{len(alias_gaps)} selected IDs** without an exact declared-ID/entry-name match and **{len(recon['entry_like_bindings_not_mapped'])} generic entry-like bindings** without a catalogue match. Many have shortened or shared root candidates. These are unresolved identity mappings, not evidence that those quests are absent. See catalogue_reconciliation.json.",'',f"Unresolved dependency origin triage: {triage}. All private references without proved origin in this run are native English lip-sync `.anims` paths; none targets a missing `towercontinued` depot. Archive absence alone cannot establish missing localized/loose-file behavior.",'', 'The sole non-identical CR1 donor is fixer_cleanup.questphase; its current SHA256 exactly matches the explicit PH1 candidate_03 successor. The donor-regression check deliberately retains UNKNOWN for a changed donor pending the full lifecycle contract; it is not a detected reversion to the broken old payload.','', 'There are 103 MAY-closure phone request contracts with listeners and native-derived acknowledgement writers present. Native `frank` → `frank_nostra` protocol aliases are evidence-backed in native_phone_protocols.json. Eight counter/cleanup associations remain UNKNOWN. Presence does not prove admission, timing, interruption handling or shared studio liveness.','', 'The first analysis and false-positive Frank findings are superseded by analysis_02. Independent raw traversal found four EmbeddedFiles containers; a separate byte scan across all 5,139 exported inputs confirmed exactly those four containers. The corrected normalization covers their graphs; their executing-container lifetime remains CONDITIONAL.',''])
