 toolroot=Path(__file__).parent;write(o/'tool_provenance.json',{'python':sys.version,'platform':platform.platform(),'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'tools':snapshot([p for p in toolroot.iterdir() if p.is_file()]),'helper':snapshot([Path('tools/build_phase2a.ps1')]),'candidate_manifest':read(o/'prepared.json'),'scope':'No compile/build/deploy operations; current results use existing captured sources'})
